            aWandererB = aWandererB + (((RotL64(aCross, 60U) + RotL64(aOrbiterC, 51U)) + aOrbiterK) + RotL64(aCarry, 51U));
            aWandererC = aWandererC ^ (((RotL64(aIngress, 5U) + RotL64(aOrbiterE, 35U)) + aOrbiterA) + aWUSaltC[((aIndex + 16U)) & S_SALT1]);
