    // [seed arx]
    READ_IN_MUTABLE_PARAMS;
    const std::uint64_t aNonceWordA = TwistMix64::DiffuseA(pNonce * 0xCEF3B5B3D79C5785ULL + 0x90848966A755B493ULL);
