            aCross ^= (RotL64(aKineticLaneD[((S_BLOCK1 - aIndex + 2086U)) & S_BLOCK1], 5U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 2391U)) & S_BLOCK1], 35U));
