            aWandererC = aWandererC ^ ((((RotL64(aPrevious, 47U) + aOrbiterA) + RotL64(aOrbiterF, 43U)) + aNonceWordO) + aWUSaltA[((aIndex + 218U)) & S_SALT1]);
            aWandererJ = aWandererJ + ((RotL64(aCross, 27U) + aOrbiterB) + RotL64(aOrbiterI, 5U));
