            aCross = (RotL64(aHeartLaneA[((S_BLOCK1 - aIndex + 9817U)) & S_BLOCK1], 3U) ^ RotL64(aHeartLaneB[((S_BLOCK1 - aIndex + 8696U)) & S_BLOCK1], 42U));
