            aOrbiterK = (((aOrbiterK + aOrbiterC) + 0x4C1FB427F41C5673ULL) + aOUSaltF[((aIndex + 433U)) & S_SALT1]) + aNonceWordD;
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0x0A522C20E69A6059ULL;
