            aOrbiterD = ((aOrbiterD ^ aOrbiterA) ^ 0xBC0C2E960B29424CULL) ^ aOUSaltA[(((511U - aIndex) + 475U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x39C337CF4C2708A1ULL), 23U);
            //
