            aWandererK = aWandererK ^ ((((RotL64(aPrevious, 13U) + RotL64(aOrbiterD, 11U)) + aOrbiterF) + aNonceWordN) + aWUSaltH[(((511U - aIndex) + 323U)) & S_SALT1]);
