    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [seed arx]
    std::uint8_t *aSource = pWorkSpace->mSourceLane;
    READ_IN_MUTABLE_PARAMS;
    const std::uint64_t aNonceWordA = TwistMix64::DiffuseB(pNonce * 0xF9E4B450C7846A61ULL + 0xD5B5D926C816249DULL);
    const std::uint64_t aNonceWordB = TwistMix64::DiffuseA(pNonce * 0xB3204C0CFBA7DAD1ULL + 0xB2966A8FB4250F9AULL);
    const std::uint64_t aNonceWordC = TwistMix64::DiffuseA(pNonce * 0x9DC1318FD1388F51ULL + 0xF4319A5C89BA6BC8ULL);
    const std::uint64_t aNonceWordD = TwistMix64::DiffuseB(pNonce * 0x897A85E307599145ULL + 0xBA09B555355ED03BULL);
