            aOrbiterA = ((aOrbiterA + aOrbiterB) + 0x5067343DFC8A1954ULL) + aOUSaltA[((aIndex + 432U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterA) ^ 0x1E7E87B62DCE3135ULL;
