            //
            aOrbiterB = ((aOrbiterB + aOrbiterE) + 0xB24A4649B1B14EA7ULL) + aOUSaltA[((aIndex + 156U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterB) ^ 0xD9E1F527C5F23568ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x2D1736E0DE4BC94FULL), 47U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterI) + 0xC1239A58F6E4A4ADULL) + aOUSaltB[(((511U - aIndex) + 281U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0xBB912C8EA9E7B584ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x5E3EF419CD51A19DULL), 27U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterG) + 0x7295E7C41AEA40EFULL;
