            aOrbiterC = RotL64((aOrbiterC * 0x74A8AC3F30A26D6FULL), 13U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterH) + 0x777ADA69BE96AFE3ULL) + aOUSaltD[(((511U - aIndex) + 107U)) & S_SALT1];
