            aWandererJ = aWandererJ ^ ((RotL64(aScatter, 13U) + aOrbiterE) + RotL64(aOrbiterH, 37U));
            aWandererG = aWandererG + ((((RotL64(aPrevious, 41U) + aOrbiterG) + RotL64(aOrbiterE, 11U)) + RotL64(aCarry, 37U)) + aWUSaltA[(((511U - aIndex) + 485U)) & S_SALT1]);
            aWandererH = aWandererH ^ ((RotL64(aCross, 37U) + RotL64(aOrbiterB, 27U)) + aOrbiterF);
            aWandererI = aWandererI + ((RotL64(aIngress, 27U) + aOrbiterK) + RotL64(aOrbiterJ, 43U));
            aWandererF = aWandererF ^ (((RotL64(aScatter, 48U) + aOrbiterI) + RotL64(aOrbiterG, 21U)) + aWUSaltB[((aIndex + 369U)) & S_SALT1]);
            aWandererB = aWandererB + ((RotL64(aPrevious, 21U) + RotL64(aOrbiterC, 5U)) + aOrbiterI);
            //
            aCarry = aCarry + (aWandererI ^ RotL64(aWandererE, 41U));
            aCarry = aCarry + (RotL64(aWandererJ, 14U) ^ aWandererH);
