            aCross ^= (RotL64(aKeyRowReadA[(((2047U - aIndex) + 10447U)) & W_KEY1], 5U) ^ RotL64(aPlasmaLaneC[((aIndex + 11964U)) & S_BLOCK1], 37U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateBDomainWordCross));
            //
            aScatter = (RotL64(aCross, 30U) + RotL64(aPrevious, 57U)) + (RotL64(aIngress, 11U) ^ RotL64(aCarry, 43U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateBDomainWordScatter));
            //
            aOrbiterA = (aWandererI + RotL64(aScatter, 29U)) + 0xA344734F12D8D6DCULL;
            aOrbiterG = (aWandererJ + RotL64(aPrevious, 48U)) + 0xB9C9A5062C445666ULL;
